agraph", "content": [{"type": "text", "text": "常识靠积累，短期突击效果有限"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "不要在常识题上花太多时间"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "不确定时选第一直觉"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "常识判断范围广、难度大，建议日常多积累。考试时控制每题30秒以内。"}]}]}]}$$ AS jsonb), NULL, '行测-常识判断模块概述。', category_node.id, CAST('["常识判断"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_common_sense", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
